-- Server-side sessions (ADR 0006). Global identity data without row-level security (ADR 0008):
-- a session is looked up before any scope exists. IDs are UUIDv7 generated by the API.

-- +goose Up
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

CREATE TABLE sessions (
    id                  uuid        PRIMARY KEY,
    user_id             uuid        NOT NULL REFERENCES users (id),
    -- SHA-256 of the 32-byte token; the token itself is never stored.
    token_hash          bytea       NOT NULL,
    created_at          timestamptz NOT NULL,
    last_seen_at        timestamptz NOT NULL,
    idle_expires_at     timestamptz NOT NULL,
    absolute_expires_at timestamptz NOT NULL,
    revoked_at          timestamptz,
    revoked_reason      text,
    ip                  inet,
    user_agent          text,
    CONSTRAINT sessions_token_hash_key UNIQUE (token_hash),
    CONSTRAINT sessions_token_hash_length CHECK (octet_length(token_hash) = 32),
    CONSTRAINT sessions_idle_within_absolute CHECK (idle_expires_at <= absolute_expires_at),
    CONSTRAINT sessions_revoked_consistent CHECK ((revoked_at IS NULL) = (revoked_reason IS NULL)),
    CONSTRAINT sessions_revoked_reason_valid
        CHECK (revoked_reason IN ('logout', 'password_changed', 'password_reset', 'signed_out_elsewhere')),
    CONSTRAINT sessions_user_agent_length CHECK (char_length(user_agent) <= 512)
);

-- "My devices" and "sign out everywhere" look up a user's active sessions.
-- The table is created empty in this same migration, so a plain index blocks nobody.
-- squawk-ignore require-concurrent-index-creation
CREATE INDEX sessions_user_id_active_idx ON sessions (user_id) WHERE revoked_at IS NULL;

-- +goose Down
-- Down undoes the Up above on a database that has not been used yet; dropping is its purpose.
-- squawk-ignore ban-drop-table
DROP TABLE sessions;
